-- Phone calls (docs/plan.md §1.19, §1.23): seconds of calls an agent placed or answered, counted into
-- usage_daily for billing (Twilio's duration of each finished call, once per call). Calls themselves
-- are raw records and contact-thread messages, so no table is added. A column with a default, so
-- the previous Worker keeps working. Generated by drizzle-kit.
ALTER TABLE "usage_daily" ADD COLUMN "call_seconds" integer DEFAULT 0 NOT NULL;
